import{j as r}from"./entry.CF4dEPSY.js";const n={"signals.0.label":"лет в промышленной разработке","signals.0.note":"От стажировки на React до senior-ответственности в международных продуктовых командах.","signals.1.label":"пользователей","signals.1.note":"Продакшн-интерфейсы, работающие на значимом для бизнеса масштабе.","signals.2.label":"проектов сдано","signals.2.note":"Веб, мобильные и данные-интенсивные платформы.","signals.3.label":"проектов оптимизировано","signals.3.note":"Улучшения производительности, архитектуры и поддерживаемости.","case_studies.01.kicker":"Архитектура на масштабе продукта","case_studies.01.title":"Сделать десять модулей одной системой.","case_studies.01.problem":"Растущей поверхности продукта на Vue нужно было оставаться согласованной, пока 10+ модулей развивались параллельно для платформы с более чем миллионом пользователей в год.","case_studies.01.solution":"Определил переиспользуемые паттерны Vue 3 / TypeScript вокруг composition, роутинга, состояния и общих продуктовых сценариев, чтобы новые фичи стартовали от готовой системы, а не локальных договорённостей.","case_studies.01.result":"Архитектура сократила время реализации фич примерно на 30% и заложила более прочную базу для разработки между модулями.","case_studies.01.metrics.0.label":"продуктовых модулей","case_studies.01.metrics.1.label":"быстрее доставка фич","case_studies.02.kicker":"Производительность как архитектура","case_studies.02.title":"Относиться ко времени загрузки как к графу, а не числу.","case_studies.02.problem":"Высоконагруженные экраны замедлялись из-за работы, распределённой между рендерингом, получением данных, кэшированием и асинхронными UI-потоками, а не из-за одного очевидного узкого места.","case_studies.02.solution":"Оптимизировал весь путь от запроса до рендера: поведение рендеринга, кэширование, асинхронную оркестрацию и паттерны API-запросов, подкрепив работу Core Web Vitals, Lighthouse, тестами и мониторингом Sentry.","case_studies.02.result":"Среднее время загрузки страницы снизилось примерно с 3.2 до 2.1 секунды, пока платформа продолжала развиваться.","case_studies.02.metrics.0.label":"средняя загрузка страницы","case_studies.02.metrics.1.label":"примерное снижение","case_studies.03.kicker":"Производительность геоданных","case_studies.03.title":"Полмиллиона объектов на карте должны оставаться интерактивными.","case_studies.03.problem":"Плотным GIS-интерфейсам нужно было рендерить и обрабатывать наборы данных из примерно 300–500 тыс. геопространственных объектов, не делая первое взаимодействие ощутимо медленным.","case_studies.03.solution":"Перестроил слои и стили, внедрил кластеризацию и фильтрацию на клиенте, а также сократил лишнюю работу на пути данных Vuex–Elasticsearch.","case_studies.03.result":"Начальный рендеринг Mapbox GL JS упал примерно с 800 до 480 мс, плюс отдельная работа над алгоритмами дала 30%-ное улучшение скорости геопоиска.","case_studies.03.metrics.0.label":"начальный рендер карты","case_studies.03.metrics.1.label":"геопространственных объектов","case_studies.04.kicker":"Переиспользуемые системы доставки","case_studies.04.title":"Собирать следующий региональный продукт из конфигурации, а не копированием.","case_studies.04.problem":"Десятки региональных GIS-продуктов повторяли одни и те же UI- и данные-паттерны, но повторная реализация замедляла доставку и удорожала консистентность.","case_studies.04.solution":"Создал централизованную архитектуру со 100+ переиспользуемыми Vue-компонентами и общими модулями, затем стандартизировал BEM, теминг, ролевые паттерны, линтинг и практики тестирования вокруг неё.","case_studies.04.result":"Похожая реализация стала занимать до 50% меньше времени; некоторые запуски, ранее занимавшие около месяца, стали укладываться примерно в неделю.","case_studies.04.metrics.0.label":"переиспользуемых компонентов","case_studies.04.metrics.1.label":"похожих реализаций","surfaces.A.title":"Высоконагруженные продуктовые модули","surfaces.A.text":"Интерфейсы, где архитектура, кэширование, состояние и поведение API должны работать как единая продуктовая система.","surfaces.B.title":"Геопространственные системы","surfaces.B.text":"Продукты с большим количеством карт, где объём данных меняет саму фронтенд-архитектуру, а не только слой рендеринга.","surfaces.C.title":"Программы модернизации","surfaces.C.text":"Переход с legacy на современный стек, который не останавливает доставку продукта, пока меняется техническая основа.","surfaces.D.title":"End-to-end доставка продукта","surfaces.D.text":"Фронтенд-инженерия с достаточной глубиной бэкенда, чтобы владеть API, границами интеграций и поведением в production.","principles.01.title":"Сначала измерить, потом переписывать.","principles.01.text":"Изменение производительности должно начинаться с фактов и заканчиваться результатом, заметным пользователю.","principles.02.title":"Архитектура — это инструмент доставки.","principles.02.text":"Лучшая абстракция — та, что делает следующую фичу дешевле, безопаснее и понятнее.","principles.03.title":"Фронтенд — часть системы.","principles.03.text":"Рендеринг, форма данных, API, доступность, наблюдаемость и релизные пайплайны — одна инженерная поверхность.","principles.04.title":"Senior — значит снижать неопределённость.","principles.04.text":"Техническое лидерство — это делать компромиссы видимыми, чтобы команда двигалась быстро, не накапливая скрытых рисков.","milestones.Ciklum.role":"Senior Software Engineer","milestones.Ciklum.focus":"Фронтенд-архитектура · модернизация продукта · производительность · техническое лидерство","milestones.KeyHorse.role":"Middle → Senior Software Engineer · Team Lead","milestones.KeyHorse.focus":"GIS · цифровые двойники · переиспользуемые системы · backend API · менторство","milestones.DAR.role":"Junior Software Engineer","milestones.DAR.focus":"Высокообъёмная веб-разработка · e-commerce · мобильные приложения · производительность","milestones.EPAM Systems.role":"Software Engineer Intern","milestones.EPAM Systems.focus":"React · TypeScript · переиспользуемый UI · инженерные основы","proof_items.0.label":"Образование","proof_items.0.value":"Информационные системы","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"Английский","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Академический IELTS · результат CEFR C1","proof_items.2.label":"Признание","proof_items.2.value":"Серебряная медаль","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — международный конкурс компьютерных проектов.","proof_items.3.label":"Рекомендация","proof_items.3.value":"KeyHorse","proof_items.3.note":"Подписанная рекомендация от руководства компании","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Результат академического IELTS (CEFR C1) — подтверждение свободного профессионального английского для международных, remote-first инженерных ролей.","proof_documents.chinese-proficiency.title":"Владение китайским языком","proof_documents.chinese-proficiency.description":"Базовый уровень китайского языка, развитый параллельно с профессиональной работой с трансграничными продуктовыми и бизнес-командами.","proof_documents.infomatrix.title":"Серебряная медаль — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Признание на международном конкурсе компьютерных проектов за одну из ранних инженерных работ.","proof_documents.keyhorse.title":"Рекомендательное письмо — KeyHorse","proof_documents.keyhorse.description":"Подписанная рекомендация на бланке KeyHorse, рекомендующая Жасулана на инженерную позицию senior-уровня.","projects.geonomix.description":"Масштабная геопространственная платформа и цифровой двойник, объединяющая интерактивные карты, муниципальные данные, цифровые реестры, госуслуги и инструменты мониторинга в региональных внедрениях.","projects.midas-event.description":"Сайт event-агентства, построенный как просматриваемое портфолио прошедших мероприятий, а не статичный список услуг, с интерактивными деталями на React.","projects.kostyum.description":"Адаптивный фронтенд e-commerce для мужской моды с переиспользуемым UI каталога товаров и упором на плавный опыт покупок на десктопе и мобильных.","projects.unistory.description":"Интерфейс цифрового продукта, интегрирующий состояние крипто-кошелька и асинхронные данные бэкенда в переиспользуемые продуктовые компоненты на React.","projects.kazmed.description":"Корпоративный фронтенд для авторизованного партнёра по обслуживанию медицинского оборудования, построенный вокруг каталога на Swiper вместо длинных текстовых страниц.","projects.dostyk-trans-terminal.description":"Корпоративный сайт логистического терминала на переходе Достык–Алашанькоу, представляющий услуги обработки, хранения и перевалки контейнеров.","projects.melissa.description":"Крупная онлайн-аптека с 13 000+ товаров, включая навигацию по каталогу, поиск, фильтрацию, сортировку, страницы товаров, корзину и интеграции с бэкендом.","projects.abi-construction.description":"Сайт строительной компании, сочетающий CMS-бэкенд на WordPress с интерактивными галереями проектов на Vue.","projects.tahit.description":"Фронтенд производственной компании, демонстрирующий возможности текстильного производства, технологии, продукцию и услуги на десктопе и мобильных.","projects.dobraya.description":"Витрина онлайн-аптеки с адаптивными каталогами, навигацией по категориям, поиском, фильтрацией и сценариями оформления заказа.","projects.asia-mebel.description":"Коммерческий каталог мебельных материалов, фурнитуры, инструментов и услуг со структурированной навигацией, фильтрацией, поиском и страницами товаров.","projects.pharmacom.description":"Сайт для сети прививочных клиник и аптек, организованный вокруг локаций, услуг и информации для пациентов, а не одной статичной главной страницы.","projects.navat.description":"Промо-лендинг ресторана с адаптивным визуальным опытом, выстроенным вокруг меню, атмосферы и бренда.","projects.asia-credit-bank.description":"Сайт контакт-центра банка, превращающий большой набор страниц с продуктами и поддержкой в быструю, удобную для навигации структуру.","projects.geonomix.note":"Продукт, где карта — главное, а объём данных и переиспользуемая региональная доставка определили фронтенд-архитектуру.","projects.melissa.note":"Опыт крупного каталога, где информационная архитектура важна не меньше, чем полировка интерфейса."},a={"signals.0.label":"жыл өндірістік тәжірибе","signals.0.note":"React тәжірибешісінен халықаралық өнім командаларындағы senior жауапкершілікке дейін.","signals.1.label":"пайдаланушыға қызмет көрсетілді","signals.1.note":"Маңызды бизнес ауқымында жұмыс істейтін production интерфейстер.","signals.2.label":"жоба тапсырылды","signals.2.note":"Веб, мобильді және деректерге бай платформалар бойынша.","signals.3.label":"жоба оңтайландырылды","signals.3.note":"Өнімділік, архитектура және қолдауға жарамдылықты жақсарту.","case_studies.01.kicker":"Өнім ауқымындағы архитектура","case_studies.01.title":"Он модульді бір жүйедей сезіндіру.","case_studies.01.problem":"Жылына миллионнан астам пайдаланушыға қызмет көрсететін платформада 10+ модуль қатар дамып жатқанда, өсіп келе жатқан Vue өнімінің беті бірізді болып қалуы керек еді.","case_studies.01.solution":"Composition, роутинг, күй және ортақ өнім сценарийлері айналасында қайта пайдалануға болатын Vue 3 / TypeScript үлгілерін анықтадым, сол арқылы жаңа функциялар жергілікті келісімдерден емес, дайын жүйеден басталатын болды.","case_studies.01.result":"Архитектура функцияны іске асыру уақытын шамамен 30%-ға қысқартты және модульаралық дамуға берік негіз қалады.","case_studies.01.metrics.0.label":"өнім модулі","case_studies.01.metrics.1.label":"функцияны тезірек жеткізу","case_studies.02.kicker":"Архитектура ретіндегі өнімділік","case_studies.02.title":"Жүктелу уақытын санмен емес, графикпен қарау.","case_studies.02.problem":"Жоғары трафикті экрандар бір анық тар жерден емес, рендеринг, деректерді алу, кэштеу және асинхронды UI ағындары арасында бөлінген жұмыстан баяулап жатты.","case_studies.02.solution":"Сұраныстан рендерге дейінгі бүкіл жолды оңтайландырдым: рендеринг тәртібін, кэштеуді, асинхронды оркестрацияны және API сұраныс үлгілерін, содан кейін бұл жұмысты Core Web Vitals, Lighthouse, тесттер және Sentry мониторингімен нығайттым.","case_studies.02.result":"Платформа дами беруіне қарамастан, беттің орташа жүктелу уақыты шамамен 3.2 секундтан 2.1 секундқа дейін қысқарды.","case_studies.02.metrics.0.label":"орташа бет жүктелуі","case_studies.02.metrics.1.label":"шамамен төмендеу","case_studies.03.kicker":"Геодеректер өнімділігі","case_studies.03.title":"Жарты миллион карта нысаны әлі де интерактивті болуы тиіс.","case_studies.03.problem":"Тығыз GIS интерфейстері бірінші өзара әрекеттесуді байқалатындай баяулатпай, шамамен 300–500 мың геокеңістіктік нысаннан тұратын деректер жиынын рендерлеп, өңдеуі керек болды.","case_studies.03.solution":"Қабаттар мен стильдерді қайта құрдым, кластерлеу мен клиент жағындағы сүзгілеуді енгіздім және Vuex–Elasticsearch деректер жолындағы қайталанатын жұмысты жойдым.","case_studies.03.result":"Mapbox GL JS бастапқы рендерингі шамамен 800 мс-тан 480 мс-қа дейін төмендеді, ал алгоритмдер бойынша бөлек жұмыс геоіздеу жылдамдығын 30%-ға жақсартты.","case_studies.03.metrics.0.label":"бастапқы карта рендері","case_studies.03.metrics.1.label":"геокеңістіктік нысан","case_studies.04.kicker":"Қайта пайдалануға болатын жеткізу жүйелері","case_studies.04.title":"Келесі аймақтық өнімді көшіру арқылы емес, баптау арқылы құру.","case_studies.04.problem":"Ондаған аймақтық GIS өнімдері бір-біріне ұқсас UI және деректер үлгілерін қайталады, бірақ қайта іске асыру жеткізуді баяулатып, бірізділікті қымбаттатты.","case_studies.04.solution":"100+ қайта пайдалануға болатын Vue компоненттері мен ортақ модульдерден тұратын орталықтандырылған архитектура жасадым, содан кейін оның айналасында BEM, теминг, рөлге негізделген үлгілер, линтинг және тестілеу тәжірибелерін стандарттадым.","case_studies.04.result":"Ұқсас іске асыру жұмысы 50%-ға дейін азайды; бұрын шамамен бір ай алатын кейбір іске қосулар енді шамамен бір аптаға сыятын болды.","case_studies.04.metrics.0.label":"қайта пайдаланылатын компонент","case_studies.04.metrics.1.label":"ұқсас іске асыру","surfaces.A.title":"Жоғары трафикті өнім модульдері","surfaces.A.text":"Архитектура, кэштеу, күй және API тәртібі бір өнім жүйесі ретінде жұмыс істеуі тиіс интерфейстер.","surfaces.B.title":"Геокеңістіктік жүйелер","surfaces.B.text":"Деректер көлемі тек рендеринг қабатын емес, фронтенд архитектурасының өзін өзгертетін карта негізіндегі өнімдер.","surfaces.C.title":"Модернизация бағдарламалары","surfaces.C.text":"Техникалық негіз өзгеріп жатқанда өнімді жеткізуді тоқтатпайтын legacy-ден заманауи стекке көшу.","surfaces.D.title":"End-to-end өнім жеткізу","surfaces.D.text":"API-ды, интеграция шекараларын және production тәртібін меңгеруге жеткілікті backend тереңдігі бар frontend-бағытталған инженерия.","principles.01.title":"Алдымен өлшеу, содан кейін қайта жазу.","principles.01.text":"Өнімділік өзгерісі дәлелден басталып, пайдаланушыға көрінетін нәтижемен аяқталуы керек.","principles.02.title":"Архитектура — жеткізу құралы.","principles.02.text":"Ең жақсы абстракция — келесі функцияны арзандатып, қауіпсіз әрі түсінікті ететін абстракция.","principles.03.title":"Frontend — жүйенің бір бөлігі.","principles.03.text":"Рендеринг, деректер пішіні, API, қолжетімділік, бақылаушылық және релиз конвейерлері — бір инженерлік аймақ.","principles.04.title":"Senior болу — белгісіздікті азайту деген сөз.","principles.04.text":"Техникалық көшбасшылық — командаға жасырын тәуекел жинамай тез қозғалуға мүмкіндік беру үшін ымыраларды көрінетін ету.","milestones.Ciklum.role":"Senior Software Engineer","milestones.Ciklum.focus":"Frontend архитектурасы · өнімді модернизациялау · өнімділік · техникалық көшбасшылық","milestones.KeyHorse.role":"Middle → Senior Software Engineer · Team Lead","milestones.KeyHorse.focus":"GIS · цифрлық қосарлар · қайта пайдаланылатын жүйелер · backend API · тәлімгерлік","milestones.DAR.role":"Junior Software Engineer","milestones.DAR.focus":"Көлемді веб-жеткізу · e-commerce · мобильді қосымшалар · өнімділік","milestones.EPAM Systems.role":"Software Engineer Intern","milestones.EPAM Systems.focus":"React · TypeScript · қайта пайдаланылатын UI · инженерлік негіздер","proof_items.0.label":"Білім","proof_items.0.value":"Ақпараттық жүйелер","proof_items.0.note":"Сулейман Демирел атындағы университет · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"Ағылшын тілі","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Академиялық IELTS · CEFR C1 нәтижесі","proof_items.2.label":"Марапат","proof_items.2.value":"Күміс медаль","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — халықаралық компьютерлік жобалар байқауы.","proof_items.3.label":"Ұсыныс","proof_items.3.value":"KeyHorse","proof_items.3.note":"Компания басшылығының қолы қойылған ұсынысы","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Академиялық IELTS нәтижесі (CEFR C1) — халықаралық, remote-first инженерлік рөлдерге жарамды еркін кәсіби ағылшын тілінің дәлелі.","proof_documents.chinese-proficiency.title":"Қытай тілін білу деңгейі","proof_documents.chinese-proficiency.description":"Трансшекаралық өнім және бизнес командаларымен кәсіби жұмыс барысында дамыған қытай тілінің бастапқы деңгейі.","proof_documents.infomatrix.title":"Күміс медаль — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Алғашқы инженерлік жобаның бірі үшін халықаралық компьютерлік жобалар байқауындағы марапат.","proof_documents.keyhorse.title":"Ұсыныс хаты — KeyHorse","proof_documents.keyhorse.description":"KeyHorse бланкісінде Жасұланды senior деңгейіндегі инженерлік лауазымға ұсынатын, қолы қойылған ұсыныс хаты.","projects.geonomix.description":"Аймақтық енгізулерде интерактивті карталарды, муниципалдық деректерді, цифрлық тізілімдерді, мемлекеттік қызметтер мен мониторинг құралдарын біріктіретін ауқымды геокеңістіктік және цифрлық қосарлар платформасы.","projects.midas-event.description":"Статикалық қызметтер тізімі емес, өткен іс-шаралардың шолуға болатын портфолиосы ретінде құрылған, React негізіндегі интерактивті мазмұны бар event-агенттігінің сайты.","projects.kostyum.description":"Тауар каталогына арналған қайта пайдаланылатын UI-мен және десктоп пен мобильдегі тегіс сатып алу тәжірибесіне бағытталған ерлер сән e-commerce фронтенді.","projects.unistory.description":"Крипто-әмиян күйі мен асинхронды backend деректерін қайта пайдаланылатын React өнім компоненттеріне біріктіретін цифрлық өнім интерфейсі.","projects.kazmed.description":"Ұзақ мәтінді беттердің орнына Swiper негізіндегі каталог айналасында құрылған, авторизацияланған медициналық жабдық қызмет серіктесіне арналған корпоративтік фронтенд.","projects.dostyk-trans-terminal.description":"Достық–Алашанькоу шекара өткелінде контейнерлерді өңдеу, сақтау және тасымалдау қызметтерін көрсететін логистикалық терминалдың корпоративтік сайты.","projects.melissa.description":"13 000+ тауары бар ірі онлайн-дәріхана: каталог навигациясы, іздеу, сүзгілеу, сұрыптау, тауар беттері, себет ағыны және backend интеграциялары.","projects.abi-construction.description":"WordPress контент-бэкендін Vue негізіндегі интерактивті жоба галереяларымен біріктірген құрылыс компаниясының сайты.","projects.tahit.description":"Тоқыма өндірісінің мүмкіндіктерін, технологияларын, өнімдері мен қызметтерін десктоп пен мобильде көрсететін өндірістік компанияның фронтенді.","projects.dobraya.description":"Бейімделгіш каталогтары, санат навигациясы, іздеу, сүзгілеу және тапсырыс ағындары бар онлайн-дәріхана витринасы.","projects.asia-mebel.description":"Құрылымдалған навигациясы, сүзгілеуі, іздеуі және тауар беттері бар жиһаз материалдары, фурнитура, құралдар мен қызметтердің коммерциялық каталогы.","projects.pharmacom.description":"Бір статикалық басты бет емес, орналасу, қызметтер және пациент ақпараты айналасында құрылған вакцинация клиникасы мен дәріхана желісіне арналған сайт.","projects.navat.description":"Мәзір, атмосфера және бренд бірегейлігі айналасында құрылған, бейімделгіш көрнекі тәжірибесі бар мейрамхананың жарнамалық лендингі.","projects.asia-credit-bank.description":"Тауар мен қолдау беттерінің үлкен жиынын клиенттерге арналған жылдам, ыңғайлы навигациялы құрылымға айналдыратын банктің байланыс орталығы сайты.","projects.geonomix.note":"Карта басты орында тұрған өнім, мұнда деректер көлемі мен қайта пайдаланылатын аймақтық жеткізу фронтенд архитектурасын қалыптастырды.","projects.melissa.note":"Ақпараттық архитектура UI жылтырлығы сияқты маңызды болатын үлкен каталог тәжірибесі."},o={"signals.0.label":"yıl production deneyimi","signals.0.note":"React stajyerliğinden uluslararası ürün ekiplerinde senior sorumluluğa.","signals.1.label":"kullanıcıya ulaşıldı","signals.1.note":"Anlamlı bir ürün ölçeğinde çalışan production arayüzleri.","signals.2.label":"proje teslim edildi","signals.2.note":"Web, mobil ve veri yoğun platformlar genelinde.","signals.3.label":"proje optimize edildi","signals.3.note":"Performans, mimari ve sürdürülebilirlik iyileştirmeleri.","case_studies.01.kicker":"Ürün ölçeğinde mimari","case_studies.01.title":"On modülü tek bir sistem gibi hissettirmek.","case_studies.01.problem":"Büyüyen bir Vue ürün yüzeyinin, yılda bir milyondan fazla kullanıcıya hizmet veren bir platformda 10+ modül paralel geliştirilirken tutarlı kalması gerekiyordu.","case_studies.01.solution":"Composition, routing, state ve ortak ürün akışları etrafında yeniden kullanılabilir Vue 3 / TypeScript kalıpları tanımladım; böylece yeni özellikler yerel kurallardan değil, kurulu bir sistemden başlayabildi.","case_studies.01.result":"Bu mimari, özellik geliştirme süresini yaklaşık %30 azalttı ve modüller arası geliştirme için daha güçlü bir temel oluşturdu.","case_studies.01.metrics.0.label":"ürün modülü","case_studies.01.metrics.1.label":"daha hızlı özellik teslimi","case_studies.02.kicker":"Mimari olarak performans","case_studies.02.title":"Yüklenme süresini bir sayı değil, bir grafik olarak ele almak.","case_studies.02.problem":"Yoğun trafikli ekranlar, tek bir belirgin darboğazdan değil; render, veri çekme, önbellekleme ve asenkron UI akışları arasında dağılmış işlerden yavaşlıyordu.","case_studies.02.solution":"İstekten render'a kadar tüm yolu optimize ettim: render davranışı, önbellekleme, asenkron orkestrasyon ve API istek kalıpları; bu çalışmayı Core Web Vitals, Lighthouse, testler ve Sentry izlemesiyle destekledim.","case_studies.02.result":"Platform gelişmeye devam ederken ortalama sayfa yüklenme süresi yaklaşık 3.2 saniyeden 2.1 saniyeye düştü.","case_studies.02.metrics.0.label":"ortalama sayfa yüklenmesi","case_studies.02.metrics.1.label":"yaklaşık azalma","case_studies.03.kicker":"Coğrafi veri performansı","case_studies.03.title":"Yarım milyon harita nesnesi hâlâ etkileşimli hissettirmeli.","case_studies.03.problem":"Yoğun GIS arayüzlerinin, ilk etkileşimi belirgin şekilde geciktirmeden yaklaşık 300-500 bin coğrafi nesne içeren veri kümelerini render edip işlemesi gerekiyordu.","case_studies.03.solution":"Katmanları ve stilleri yeniden yapılandırdım, kümeleme ve istemci tarafı filtreleme ekledim; Vuex-Elasticsearch veri yolundaki tekrar eden işleri ortadan kaldırdım.","case_studies.03.result":"İlk Mapbox GL JS render süresi yaklaşık 800 ms'den 480 ms'ye düştü; ayrı bir algoritma çalışmasıyla coğrafi arama yanıt süresinde %30 iyileşme sağlandı.","case_studies.03.metrics.0.label":"ilk harita render'ı","case_studies.03.metrics.1.label":"coğrafi nesne","case_studies.04.kicker":"Yeniden kullanılabilir teslimat sistemleri","case_studies.04.title":"Bir sonraki bölgesel ürünü kopyalayarak değil, yapılandırarak inşa etmek.","case_studies.04.problem":"Onlarca bölgesel GIS ürünü aynı UI ve veri kalıplarını tekrarlıyordu; ancak tekrar eden uygulamalar teslimatı yavaşlatıp tutarlılığı pahalı hale getiriyordu.","case_studies.04.solution":"100+ yeniden kullanılabilir Vue bileşeni ve ortak modülden oluşan merkezi bir mimari kurdum, ardından bunun etrafında BEM, temalandırma, role dayalı kalıplar, lint ve test pratiklerini standartlaştırdım.","case_studies.04.result":"Benzer uygulama işleri %50'ye kadar azaldı; önceden yaklaşık bir ay süren bazı lansmanlar artık yaklaşık bir haftaya sığabiliyor.","case_studies.04.metrics.0.label":"yeniden kullanılabilir bileşen","case_studies.04.metrics.1.label":"benzer uygulama","surfaces.A.title":"Yoğun trafikli ürün modülleri","surfaces.A.text":"Mimarinin, önbelleklemenin, state'in ve API davranışının tek bir ürün sistemi gibi çalışması gereken arayüzler.","surfaces.B.title":"Coğrafi bilgi sistemleri","surfaces.B.text":"Veri hacminin sadece render katmanını değil, frontend mimarisinin kendisini değiştirdiği harita ağırlıklı ürünler.","surfaces.C.title":"Modernizasyon programları","surfaces.C.text":"Teknik temel değişirken ürün teslimatını durdurmayan legacy-den moderne geçiş süreçleri.","surfaces.D.title":"Uçtan uca ürün teslimatı","surfaces.D.text":"API'lere, entegrasyon sınırlarına ve production davranışına sahip çıkacak kadar derin backend bilgisiyle desteklenen frontend odaklı mühendislik.","principles.01.title":"Yeniden yazmadan önce ölç.","principles.01.text":"Bir performans değişikliği kanıtla başlamalı ve kullanıcının görebileceği bir sonuçla bitmeli.","principles.02.title":"Mimari bir teslimat aracıdır.","principles.02.text":"En iyi soyutlama, bir sonraki özelliği daha ucuz, daha güvenli ve daha anlaşılır hale getirendir.","principles.03.title":"Frontend, sistemin bir parçasıdır.","principles.03.text":"Render, veri şekli, API'ler, erişilebilirlik, gözlemlenebilirlik ve dağıtım süreçleri tek bir mühendislik alanıdır.","principles.04.title":"Senior olmak, belirsizliği azaltmak demektir.","principles.04.text":"Teknik liderlik, ekibin gizli risk biriktirmeden hızlı ilerleyebilmesi için ödünleşimleri görünür kılmaktır.","milestones.Ciklum.role":"Senior Software Engineer","milestones.Ciklum.focus":"Frontend mimarisi · ürün modernizasyonu · performans · teknik liderlik","milestones.KeyHorse.role":"Middle → Senior Software Engineer · Team Lead","milestones.KeyHorse.focus":"GIS · dijital ikizler · yeniden kullanılabilir sistemler · backend API · mentorluk","milestones.DAR.role":"Junior Software Engineer","milestones.DAR.focus":"Yüksek hacimli web teslimatı · e-ticaret · mobil · performans","milestones.EPAM Systems.role":"Software Engineer Intern","milestones.EPAM Systems.focus":"React · TypeScript · yeniden kullanılabilir UI · mühendislik temelleri","proof_items.0.label":"Eğitim","proof_items.0.value":"Bilişim Sistemleri","proof_items.0.note":"Suleyman Demirel Üniversitesi · 2018–2022 · Not Ortalaması 3.72 / 4.0","proof_items.1.label":"İngilizce","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Akademik IELTS · CEFR C1 sonucu","proof_items.2.label":"Tanınırlık","proof_items.2.value":"Gümüş Madalya","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — Uluslararası Bilgisayar Projesi Yarışması.","proof_items.3.label":"Referans","proof_items.3.value":"KeyHorse","proof_items.3.note":"Şirket yönetiminden imzalı referans","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Akademik IELTS sonucu (CEFR C1) — uluslararası, uzaktan çalışmaya uygun mühendislik rolleri için tam profesyonel İngilizce yeterliliğinin kanıtı.","proof_documents.chinese-proficiency.title":"Çince Dil Yeterliliği","proof_documents.chinese-proficiency.description":"Sınır ötesi ürün ve iş ekipleriyle yürütülen profesyonel çalışmayla birlikte geliştirilen temel düzey Çince yeterliliği.","proof_documents.infomatrix.title":"Gümüş Madalya — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Erken bir mühendislik projesi için Uluslararası Bilgisayar Projesi Yarışması'nda kazanılan tanınırlık.","proof_documents.keyhorse.title":"Referans Mektubu — KeyHorse","proof_documents.keyhorse.description":"Zhassulan'ı senior seviyede bir mühendislik rolü için öneren, KeyHorse antetli kağıdında imzalı bir referans mektubu.","projects.geonomix.description":"Bölgesel uygulamalarda interaktif haritaları, belediye verilerini, dijital sicilleri, kamu hizmetlerini ve izleme araçlarını bir araya getiren büyük ölçekli coğrafi bilgi ve dijital ikiz platformu.","projects.midas-event.description":"Statik bir hizmet listesi yerine geçmiş etkinliklerin gezilebilir bir portföyü olarak kurgulanmış, React tabanlı interaktif detaylara sahip bir etkinlik ajansı sitesi.","projects.kostyum.description":"Yeniden kullanılabilir ürün katalog arayüzüne sahip, masaüstü ve mobilde akıcı bir alışveriş deneyimine odaklanan responsive erkek modası e-ticaret frontend'i.","projects.unistory.description":"Kripto cüzdan durumunu ve asenkron backend verisini yeniden kullanılabilir React ürün bileşenlerine entegre eden dijital ürün arayüzü.","projects.kazmed.description":"Uzun metin sayfaları yerine Swiper tabanlı bir ekipman ve hizmet kataloğu etrafında kurulmuş, yetkili bir medikal ekipman servis ortağı için kurumsal frontend.","projects.dostyk-trans-terminal.description":"Dostyk–Alashankou sınır kapısındaki bir lojistik terminali için konteyner elleçleme, depolama ve aktarma hizmetlerini tanıtan kurumsal web sitesi.","projects.melissa.description":"13.000+ ürünlü büyük bir online eczane; katalog gezinme, arama, filtreleme, sıralama, ürün sayfaları, sepet akışları ve backend entegrasyonları içeriyor.","projects.abi-construction.description":"WordPress içerik altyapısını Vue tabanlı interaktif proje galerileriyle birleştiren bir inşaat şirketi web sitesi.","projects.tahit.description":"Tekstil üretim kapasitelerini, teknolojilerini, ürünlerini ve hizmetlerini masaüstü ve mobilde sergileyen bir üretim şirketi frontend'i.","projects.dobraya.description":"Responsive kataloglara, kategori gezinmeye, arama, filtreleme ve sipariş akışlarına sahip bir online eczane vitrini.","projects.asia-mebel.description":"Yapılandırılmış gezinme, filtreleme, arama ve ürün sayfalarına sahip mobilya malzemeleri, aksesuarlar, araçlar ve hizmetler için ticari bir katalog.","projects.pharmacom.description":"Tek bir statik ana sayfa yerine lokasyonlar, hizmetler ve hasta bilgileri etrafında organize edilmiş, bir aşı kliniği ve eczane ağı için sağlık web sitesi.","projects.navat.description":"Menü, atmosfer ve marka kimliği etrafında kurgulanmış, responsive görsel deneyime sahip tanıtım amaçlı bir restoran landing sayfası.","projects.asia-credit-bank.description":"Çok sayıda ürün ve destek sayfasını müşteriler için hızlı, kolay gezinilebilir bir yapıya dönüştüren bir banka çağrı merkezi web sitesi.","projects.geonomix.note":"Haritanın öncelikli olduğu, veri hacminin ve yeniden kullanılabilir bölgesel teslimatın frontend mimarisini şekillendirdiği bir ürün.","projects.melissa.note":"Bilgi mimarisinin UI cilası kadar önemli olduğu büyük bir katalog deneyimi."},l={"signals.0.label":"年生产环境经验","signals.0.note":"从 React 实习工作到在跨国产品团队中承担高级职责。","signals.1.label":"服务用户数","signals.1.note":"在具有实际业务规模的场景下稳定运行的生产环境界面。","signals.2.label":"个项目交付","signals.2.note":"涵盖 Web、移动端与数据密集型平台。","signals.3.label":"个项目优化","signals.3.note":"在性能、架构与可维护性方面的改进。","case_studies.01.kicker":"产品规模下的架构","case_studies.01.title":"让十个模块像一个系统一样运转。","case_studies.01.problem":"在一个年服务用户超百万的平台上，10 多个模块并行演进，日益扩张的 Vue 产品体系必须保持一致性。","case_studies.01.solution":"围绕组合式函数、路由、状态管理和通用产品流程，定义了一套可复用的 Vue 3 / TypeScript 模式，让新功能从既有体系出发，而不是各自为政。","case_studies.01.result":"该架构将功能实现时间缩短了约 30%，同时为跨模块开发打下更坚实的基础。","case_studies.01.metrics.0.label":"个产品模块","case_studies.01.metrics.1.label":"功能交付提速","case_studies.02.kicker":"性能即架构","case_studies.02.title":"把加载时间当作一张图，而不是一个数字。","case_studies.02.problem":"高流量页面变慢的原因分散在渲染、数据获取、缓存和异步 UI 流程之中，而不是某一个明显的瓶颈。","case_studies.02.solution":"优化了从请求到渲染的整条链路：渲染行为、缓存、异步编排和 API 请求模式，并借助 Core Web Vitals、Lighthouse、测试和 Sentry 监控支撑这项工作。","case_studies.02.result":"在平台持续演进的同时，平均页面加载时间从约 3.2 秒降到 2.1 秒。","case_studies.02.metrics.0.label":"平均页面加载","case_studies.02.metrics.1.label":"约降低","case_studies.03.kicker":"地理空间性能","case_studies.03.title":"五十万个地图对象依然要保持流畅交互。","case_studies.03.problem":"密集的 GIS 界面需要渲染并处理约 30 万至 50 万个地理空间对象的数据集，同时不能让首次交互变得明显迟滞。","case_studies.03.solution":"重构了图层与样式，引入聚合与客户端过滤，并精简了 Vuex 与 Elasticsearch 之间的数据链路，消除了重复计算。","case_studies.03.result":"Mapbox GL JS 的初始渲染时间从约 800 毫秒降到 480 毫秒，另外的算法优化工作又将地理搜索响应速度提升了 30%。","case_studies.03.metrics.0.label":"初始地图渲染","case_studies.03.metrics.1.label":"个地理空间对象","case_studies.04.kicker":"可复用的交付体系","case_studies.04.title":"用配置而非复制来搭建下一个区域产品。","case_studies.04.problem":"数十个区域性 GIS 产品重复着相似的 UI 与数据模式，反复实现拖慢了交付速度，也让一致性变得昂贵。","case_studies.04.solution":"构建了一套包含 100 多个可复用 Vue 组件和共享模块的集中式架构，并围绕它统一了 BEM 规范、主题、基于角色的模式、代码检查与测试实践。","case_studies.04.result":"类似功能的实现工作量最多减少 50%；一些以前需要约一个月的上线周期，现在缩短到大约一周。","case_studies.04.metrics.0.label":"个可复用组件","case_studies.04.metrics.1.label":"次类似实现","surfaces.A.title":"高流量产品模块","surfaces.A.text":"架构、缓存、状态与 API 行为必须作为同一套产品系统协同运作的界面。","surfaces.B.title":"地理空间系统","surfaces.B.text":"数据量会改变前端架构本身、而不只是渲染层的地图密集型产品。","surfaces.C.title":"现代化改造项目","surfaces.C.text":"在底层技术不断演进的同时，仍能保持产品持续交付的旧系统向现代技术栈迁移。","surfaces.D.title":"端到端的产品交付","surfaces.D.text":"以前端为主导、同时具备足够后端深度，可以掌控 API、集成边界与生产环境行为的工程实践。","principles.01.title":"先度量，再重写。","principles.01.text":"一次性能优化应当从数据出发，并以用户可感知的结果收尾。","principles.02.title":"架构是一种交付工具。","principles.02.text":"最好的抽象，是能让下一个功能开发得更便宜、更安全、更容易理解的那一种。","principles.03.title":"前端是系统的一部分。","principles.03.text":"渲染、数据结构、API、无障碍、可观测性与发布流水线，本质上是同一片工程领域。","principles.04.title":"所谓 Senior，就是降低不确定性。","principles.04.text":"技术领导力，就是把权衡取舍讲清楚，让团队能快速前进，而不是悄悄积累风险。","milestones.Ciklum.role":"高级软件工程师","milestones.Ciklum.focus":"前端架构 · 产品现代化改造 · 性能优化 · 技术领导力","milestones.KeyHorse.role":"中级 → 高级软件工程师 · 技术组长","milestones.KeyHorse.focus":"GIS · 数字孪生 · 可复用系统 · 后端 API · 团队带教","milestones.DAR.role":"初级软件工程师","milestones.DAR.focus":"高产出网页交付 · 电商 · 移动端 · 性能优化","milestones.EPAM Systems.role":"软件工程实习生","milestones.EPAM Systems.focus":"React · TypeScript · 可复用 UI · 工程基础","proof_items.0.label":"教育背景","proof_items.0.value":"信息系统专业","proof_items.0.note":"苏莱曼·德米雷尔大学 · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"英语","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"学术类雅思 · CEFR C1 水平","proof_items.2.label":"获奖","proof_items.2.value":"银牌","proof_items.2.note":"Infomatrix Asia-Pacific 2018 —— 国际计算机项目竞赛。","proof_items.3.label":"推荐","proof_items.3.value":"KeyHorse","proof_items.3.note":"来自公司管理层签署的推荐信","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"学术类雅思成绩（CEFR C1）——证明具备胜任国际化、远程优先工程岗位所需的全面专业英语能力。","proof_documents.chinese-proficiency.title":"中文水平证明","proof_documents.chinese-proficiency.description":"在与跨境产品及业务团队的专业合作中同步培养起来的基础中文水平。","proof_documents.infomatrix.title":"银牌——Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"早期一个软件工程项目在国际计算机项目竞赛中获得的认可。","proof_documents.keyhorse.title":"推荐信——KeyHorse","proof_documents.keyhorse.description":"一封使用 KeyHorse official 信头、已签署的推荐信，推荐 Zhassulan 担任高级工程岗位。","projects.geonomix.description":"一个大型地理信息与数字孪生平台，在区域部署中整合了交互式地图、市政数据、数字登记系统、政务服务与监控工具。","projects.midas-event.description":"一个活动策划公司的网站，被设计成可浏览的往期活动作品集，而非静态服务列表，通篇采用 React 打造的交互式细节展示。","projects.kostyum.description":"一个响应式男装电商前端，具备可复用的商品目录 UI，专注于在桌面端与移动端提供流畅的购物体验。","projects.unistory.description":"一个数字产品界面，将加密钱包状态和异步后端数据整合进可复用的 React 产品组件中。","projects.kazmed.description":"为一家获授权的医疗设备服务合作伙伴打造的企业前端，围绕基于 Swiper 的设备与服务目录构建，而非冗长的文字页面。","projects.dostyk-trans-terminal.description":"一个位于多斯特克—阿拉山口口岸的物流枢纽企业网站，展示集装箱装卸、仓储与转运服务。","projects.melissa.description":"一家拥有 13,000 多种商品的大型在线药店，包含目录导航、搜索、筛选、排序、商品页面、购物车流程及后端集成。","projects.abi-construction.description":"一家建筑公司的网站，将 WordPress 内容后台与基于 Vue 构建的交互式项目展示画廊结合在一起。","projects.tahit.description":"一家制造企业的前端，在桌面端与移动端展示其纺织生产能力、技术、产品与服务。","projects.dobraya.description":"一个在线药店的前台展示页面，具备响应式目录、分类导航、搜索、筛选与下单流程。","projects.asia-mebel.description":"一个家具材料、五金配件、工具与相关服务的商用目录，具有结构化导航、筛选、搜索与商品页面。","projects.pharmacom.description":"为一家疫苗接种诊所及药店网络打造的医疗健康网站，围绕门店位置、服务项目与患者信息组织内容，而非单一的静态首页。","projects.navat.description":"一个餐厅宣传落地页，围绕菜单、氛围与品牌形象打造出响应式的视觉体验。","projects.asia-credit-bank.description":"一个银行客服中心网站，把大量产品与支持类页面整合成快速、易于浏览的结构，方便客户查找信息。","projects.geonomix.note":"一个以地图为核心的产品，数据体量与可复用的区域化交付方式共同决定了前端架构。","projects.melissa.note":"一个大型商品目录场景，信息架构的重要性不亚于界面打磨本身。"},c={"signals.0.label":"jaar in productie-ontwikkeling","signals.0.note":"Van een React-stage tot senior verantwoordelijkheid in internationale productteams.","signals.1.label":"gebruikers","signals.1.note":"Productie-interfaces die draaien op een schaal die van belang is voor het bedrijf.","signals.2.label":"opgeleverde projecten","signals.2.note":"Web-, mobiele en data-intensieve platforms.","signals.3.label":"geoptimaliseerde projecten","signals.3.note":"Verbeteringen in performance, architectuur en onderhoudbaarheid.","case_studies.01.kicker":"Architectuur op productschaal","case_studies.01.title":"Tien modules tot één systeem maken.","case_studies.01.problem":"Een groeiend Vue-productoppervlak moest consistent blijven terwijl 10+ modules parallel evolueerden voor een platform met meer dan een miljoen gebruikers per jaar.","case_studies.01.solution":"Ik definieerde herbruikbare Vue 3/TypeScript-patronen voor composition, routing, state en gedeelde productscenario’s, zodat nieuwe features starten vanuit een kant-en-klaar systeem in plaats van lokale afspraken.","case_studies.01.result":"De architectuur verkortte de implementatietijd van features met ongeveer 30% en legde een steviger fundament voor ontwikkeling tussen modules.","case_studies.01.metrics.0.label":"productmodules","case_studies.01.metrics.1.label":"snellere feature-levering","case_studies.02.kicker":"Performance als architectuur","case_studies.02.title":"Laadtijd behandelen als een graaf, niet als een getal.","case_studies.02.problem":"Zwaarbelaste schermen werden trager door werk dat verspreid was over rendering, data-ophaling, caching en asynchrone UI-stromen — niet door één duidelijk knelpunt.","case_studies.02.solution":"Ik optimaliseerde het volledige pad van aanvraag tot rendering: renderinggedrag, caching, asynchrone orkestratie en API-verzoekpatronen, ondersteund door Core Web Vitals, Lighthouse, tests en Sentry-monitoring.","case_studies.02.result":"De gemiddelde paginalaadtijd daalde van ongeveer 3,2 naar 2,1 seconden, terwijl het platform bleef groeien.","case_studies.02.metrics.0.label":"gemiddelde laadtijd","case_studies.02.metrics.1.label":"geschatte afname","case_studies.03.kicker":"Geodata-performance","case_studies.03.title":"Een half miljoen kaartobjecten moeten interactief blijven.","case_studies.03.problem":"Dichte GIS-interfaces moesten datasets van ongeveer 300.000–500.000 geo-objecten renderen en verwerken zonder de eerste interactie merkbaar te vertragen.","case_studies.03.solution":"Ik bouwde lagen en stijlen opnieuw op, introduceerde client-side clustering en filtering, en verminderde overbodig werk in het Vuex-Elasticsearch-datapad.","case_studies.03.result":"De initiële rendering van Mapbox GL JS daalde van ongeveer 800 naar 480 ms, en apart algoritmewerk leverde een verbetering van 30% in geo-zoeksnelheid op.","case_studies.03.metrics.0.label":"initiële kaartrendering","case_studies.03.metrics.1.label":"geo-objecten","case_studies.04.kicker":"Herbruikbare leversystemen","case_studies.04.title":"Het volgende regionale product samenstellen uit configuratie, niet door te kopiëren.","case_studies.04.problem":"Tientallen regionale GIS-producten herhaalden dezelfde UI- en datapatronen, maar herimplementatie vertraagde de levering en maakte consistentie duurder.","case_studies.04.solution":"Ik bouwde een gecentraliseerde architectuur met 100+ herbruikbare Vue-componenten en gedeelde modules, en standaardiseerde daarop BEM, theming, rolpatronen, linting en testpraktijken.","case_studies.04.result":"Een vergelijkbare implementatie kostte tot 50% minder tijd; sommige lanceringen die eerder ongeveer een maand kostten, pasten nu in ongeveer een week.","case_studies.04.metrics.0.label":"herbruikbare componenten","case_studies.04.metrics.1.label":"vergelijkbare implementaties","surfaces.A.title":"Zwaarbelaste productmodules","surfaces.A.text":"Interfaces waar architectuur, caching, state en API-gedrag moeten functioneren als één productsysteem.","surfaces.B.title":"Geospatiale systemen","surfaces.B.text":"Kaartrijke producten waar het datavolume de frontend-architectuur zelf vormt, niet alleen de renderlaag.","surfaces.C.title":"Moderniseringsprogramma’s","surfaces.C.text":"De overgang van legacy naar een moderne stack zonder de productlevering te stoppen terwijl de technische basis verandert.","surfaces.D.title":"End-to-end productlevering","surfaces.D.text":"Frontend-engineering met genoeg backend-diepgang om API’s, integratiegrenzen en productiegedrag te beheren.","principles.01.title":"Eerst meten, dan herschrijven.","principles.01.text":"Een performanceverandering moet beginnen met feiten en eindigen met een resultaat dat de gebruiker merkt.","principles.02.title":"Architectuur is een leverinstrument.","principles.02.text":"De beste abstractie is degene die de volgende feature goedkoper, veiliger en begrijpelijker maakt.","principles.03.title":"Frontend is onderdeel van het systeem.","principles.03.text":"Rendering, datavorm, API’s, toegankelijkheid, observability en release-pipelines zijn één technisch geheel.","principles.04.title":"Senior zijn betekent onzekerheid verminderen.","principles.04.text":"Technisch leiderschap betekent afwegingen zichtbaar maken zodat het team snel vooruit kan zonder verborgen risico’s op te bouwen.","milestones.Ciklum.role":"Senior Software Engineer","milestones.Ciklum.focus":"Frontend-architectuur · productmodernisering · performance · technisch leiderschap","milestones.KeyHorse.role":"Middle → Senior Software Engineer · Team Lead","milestones.KeyHorse.focus":"GIS · digital twins · herbruikbare systemen · backend-API’s · mentoring","milestones.DAR.role":"Junior Software Engineer","milestones.DAR.focus":"Hoogvolume webontwikkeling · e-commerce · mobiele apps · performance","milestones.EPAM Systems.role":"Software Engineer Stagiair","milestones.EPAM Systems.focus":"React · TypeScript · herbruikbare UI · technische basis","proof_items.0.label":"Opleiding","proof_items.0.value":"Informatiesystemen","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3,72/4,0","proof_items.1.label":"Engels","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Academic IELTS · CEFR C1-resultaat","proof_items.2.label":"Erkenning","proof_items.2.value":"Zilveren medaille","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — internationale computerprojectwedstrijd.","proof_items.3.label":"Aanbeveling","proof_items.3.value":"KeyHorse","proof_items.3.note":"Ondertekende aanbeveling van het bedrijfsmanagement","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Resultaat van de Academic IELTS (CEFR C1) — bewijs van vloeiend, professioneel Engels voor internationale, remote-first engineeringfuncties.","proof_documents.chinese-proficiency.title":"Chinese taalvaardigheid","proof_documents.chinese-proficiency.description":"Basiskennis van het Chinees, ontwikkeld naast professioneel werk met grensoverschrijdende product- en businessteams.","proof_documents.infomatrix.title":"Zilveren medaille — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Erkenning bij een internationale computerprojectwedstrijd voor een van zijn vroege technische werken.","proof_documents.keyhorse.title":"Aanbevelingsbrief — KeyHorse","proof_documents.keyhorse.description":"Ondertekende aanbeveling op briefpapier van KeyHorse, waarin Zhassulan wordt aanbevolen voor een senior engineering-functie.","projects.geonomix.description":"Grootschalig geospatiaal platform en digital twin dat interactieve kaarten, gemeentelijke data, digitale registers, overheidsdiensten en monitoringtools combineert in regionale implementaties.","projects.midas-event.description":"Website van een eventbureau, opgebouwd als een doorbladerbaar portfolio van eerdere evenementen in plaats van een statische dienstenlijst, met interactieve details in React.","projects.kostyum.description":"Responsief e-commerce-frontend voor herenmode met herbruikbare productcatalogus-UI en focus op een soepele winkelervaring op desktop en mobiel.","projects.unistory.description":"Digitale productinterface die crypto-wallet-status en asynchrone backend-data integreert in herbruikbare React-productcomponenten.","projects.kazmed.description":"Zakelijk frontend voor een erkende servicepartner voor medische apparatuur, opgebouwd rond een Swiper-catalogus in plaats van lange tekstpagina’s.","projects.dostyk-trans-terminal.description":"Zakelijke website voor een logistiek terminal bij de grensovergang Dostyk–Alashankou, met diensten voor containeroverslag, opslag en doorvoer.","projects.melissa.description":"Grote online apotheek met meer dan 13.000 producten, inclusief catalogusnavigatie, zoeken, filteren, sorteren, productpagina’s, winkelwagen en backend-integraties.","projects.abi-construction.description":"Website van een bouwbedrijf die een WordPress CMS-backend combineert met interactieve projectgalerijen in Vue.","projects.tahit.description":"Frontend van een productiebedrijf dat textielproductiecapaciteit, technologie, producten en diensten toont op desktop en mobiel.","projects.dobraya.description":"Etalage van een online apotheek met responsieve catalogi, categorienavigatie, zoeken, filteren en afrekenstromen.","projects.asia-mebel.description":"Commerciële catalogus voor meubelmaterialen, beslag, gereedschap en diensten met gestructureerde navigatie, filtering, zoeken en productpagina’s.","projects.pharmacom.description":"Website voor een netwerk van vaccinatieklinieken en apotheken, georganiseerd rond locaties, diensten en patiënteninformatie in plaats van één statische homepage.","projects.navat.description":"Promotionele landingspagina voor een restaurant met een responsieve visuele ervaring rond menu, sfeer en merk.","projects.asia-credit-bank.description":"Website van het klantcontactcentrum van een bank die een grote verzameling product- en supportpagina’s omzet in een snelle, gemakkelijk navigeerbare structuur.","projects.geonomix.note":"Een product waarbij de kaart centraal staat en datavolume plus herbruikbare regionale levering de frontend-architectuur bepaalden.","projects.melissa.note":"Ervaring met een grote catalogus waarbij informatiearchitectuur net zo belangrijk is als UI-polish."},d={"signals.0.label":"Jahre in der Produktentwicklung","signals.0.note":"Vom React-Praktikum bis zur Senior-Verantwortung in internationalen Produktteams.","signals.1.label":"Nutzer","signals.1.note":"Produktions-Interfaces, die in einem für das Geschäft relevanten Maßstab laufen.","signals.2.label":"ausgelieferte Projekte","signals.2.note":"Web-, Mobile- und datenintensive Plattformen.","signals.3.label":"optimierte Projekte","signals.3.note":"Verbesserungen bei Performance, Architektur und Wartbarkeit.","case_studies.01.kicker":"Architektur im Produktmaßstab","case_studies.01.title":"Zehn Module zu einem System machen.","case_studies.01.problem":"Eine wachsende Vue-Produktoberfläche musste konsistent bleiben, während sich 10+ Module parallel für eine Plattform mit über einer Million Nutzern pro Jahr weiterentwickelten.","case_studies.01.solution":"Ich definierte wiederverwendbare Vue 3/TypeScript-Muster für Composition, Routing, State und gemeinsame Produktszenarien, damit neue Features von einem fertigen System statt von lokalen Absprachen ausgehen.","case_studies.01.result":"Die Architektur senkte die Umsetzungszeit für Features um etwa 30 % und schuf eine solidere Basis für die modulübergreifende Entwicklung.","case_studies.01.metrics.0.label":"Produktmodule","case_studies.01.metrics.1.label":"schnellere Feature-Auslieferung","case_studies.02.kicker":"Performance als Architektur","case_studies.02.title":"Ladezeit als Graph behandeln, nicht als Zahl.","case_studies.02.problem":"Stark frequentierte Bildschirme wurden langsamer durch Arbeit, die über Rendering, Datenabruf, Caching und asynchrone UI-Abläufe verteilt war — nicht durch einen einzelnen offensichtlichen Engpass.","case_studies.02.solution":"Ich optimierte den gesamten Weg von der Anfrage bis zum Rendern: Rendering-Verhalten, Caching, asynchrone Orchestrierung und API-Anfragemuster, abgesichert durch Core Web Vitals, Lighthouse, Tests und Sentry-Monitoring.","case_studies.02.result":"Die durchschnittliche Seitenladezeit sank von etwa 3,2 auf 2,1 Sekunden, während sich die Plattform weiterentwickelte.","case_studies.02.metrics.0.label":"durchschnittliche Ladezeit","case_studies.02.metrics.1.label":"ungefähre Reduzierung","case_studies.03.kicker":"Geodaten-Performance","case_studies.03.title":"Eine halbe Million Kartenobjekte müssen interaktiv bleiben.","case_studies.03.problem":"Dichte GIS-Interfaces mussten Datensätze von etwa 300.000–500.000 Geo-Objekten rendern und verarbeiten, ohne die erste Interaktion spürbar zu verlangsamen.","case_studies.03.solution":"Ich baute Layer und Styles neu auf, führte clientseitiges Clustering und Filtern ein und reduzierte überflüssige Arbeit im Vuex-Elasticsearch-Datenpfad.","case_studies.03.result":"Das initiale Rendering von Mapbox GL JS fiel von etwa 800 auf 480 ms, zusätzlich brachte separate Algorithmusarbeit eine 30%ige Verbesserung der Geosuche-Geschwindigkeit.","case_studies.03.metrics.0.label":"initiales Karten-Rendering","case_studies.03.metrics.1.label":"Geo-Objekte","case_studies.04.kicker":"Wiederverwendbare Liefersysteme","case_studies.04.title":"Das nächste regionale Produkt aus Konfiguration statt Kopieren zusammensetzen.","case_studies.04.problem":"Dutzende regionale GIS-Produkte wiederholten dieselben UI- und Datenmuster, aber die erneute Implementierung verlangsamte die Lieferung und verteuerte die Konsistenz.","case_studies.04.solution":"Ich schuf eine zentralisierte Architektur mit 100+ wiederverwendbaren Vue-Komponenten und gemeinsamen Modulen und standardisierte darauf aufbauend BEM, Theming, Rollenmuster, Linting und Testpraktiken.","case_studies.04.result":"Eine ähnliche Implementierung dauerte bis zu 50 % weniger Zeit; manche Einführungen, die früher etwa einen Monat dauerten, passten nun in etwa eine Woche.","case_studies.04.metrics.0.label":"wiederverwendbare Komponenten","case_studies.04.metrics.1.label":"ähnliche Implementierungen","surfaces.A.title":"Stark frequentierte Produktmodule","surfaces.A.text":"Interfaces, bei denen Architektur, Caching, State und API-Verhalten als ein einziges Produktsystem funktionieren müssen.","surfaces.B.title":"Geodatensysteme","surfaces.B.text":"Kartenreiche Produkte, bei denen das Datenvolumen die Frontend-Architektur selbst prägt, nicht nur die Rendering-Ebene.","surfaces.C.title":"Modernisierungsprogramme","surfaces.C.text":"Der Übergang von Legacy zu einem modernen Stack, ohne die Produktlieferung zu stoppen, während sich das technische Fundament ändert.","surfaces.D.title":"End-to-End-Produktlieferung","surfaces.D.text":"Frontend-Engineering mit genug Backend-Tiefe, um APIs, Integrationsgrenzen und Produktionsverhalten zu verantworten.","principles.01.title":"Erst messen, dann umschreiben.","principles.01.text":"Eine Performance-Änderung sollte mit Fakten beginnen und mit einem für Nutzer spürbaren Ergebnis enden.","principles.02.title":"Architektur ist ein Lieferwerkzeug.","principles.02.text":"Die beste Abstraktion ist die, die das nächste Feature günstiger, sicherer und verständlicher macht.","principles.03.title":"Frontend ist Teil des Systems.","principles.03.text":"Rendering, Datenform, APIs, Barrierefreiheit, Observability und Release-Pipelines sind eine einzige technische Oberfläche.","principles.04.title":"Senior zu sein heißt, Unsicherheit zu reduzieren.","principles.04.text":"Technische Führung bedeutet, Kompromisse sichtbar zu machen, damit das Team schnell vorankommt, ohne verborgene Risiken anzuhäufen.","milestones.Ciklum.role":"Senior Software Engineer","milestones.Ciklum.focus":"Frontend-Architektur · Produktmodernisierung · Performance · technische Führung","milestones.KeyHorse.role":"Middle → Senior Software Engineer · Team Lead","milestones.KeyHorse.focus":"GIS · digitale Zwillinge · wiederverwendbare Systeme · Backend-APIs · Mentoring","milestones.DAR.role":"Junior Software Engineer","milestones.DAR.focus":"Hochvolumige Webentwicklung · E-Commerce · mobile Apps · Performance","milestones.EPAM Systems.role":"Software Engineer Praktikant","milestones.EPAM Systems.focus":"React · TypeScript · wiederverwendbares UI · technische Grundlagen","proof_items.0.label":"Ausbildung","proof_items.0.value":"Informationssysteme","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3,72/4,0","proof_items.1.label":"Englisch","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Academic IELTS · CEFR-C1-Ergebnis","proof_items.2.label":"Auszeichnung","proof_items.2.value":"Silbermedaille","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — internationaler Computerprojekt-Wettbewerb.","proof_items.3.label":"Empfehlung","proof_items.3.value":"KeyHorse","proof_items.3.note":"Unterschriebene Empfehlung der Unternehmensleitung","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Ergebnis des Academic IELTS (CEFR C1) — Nachweis fließenden, professionellen Englisch für internationale, remote-first Engineering-Rollen.","proof_documents.chinese-proficiency.title":"Chinesischkenntnisse","proof_documents.chinese-proficiency.description":"Grundkenntnisse in Chinesisch, entwickelt parallel zur beruflichen Arbeit mit grenzüberschreitenden Produkt- und Geschäftsteams.","proof_documents.infomatrix.title":"Silbermedaille — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Auszeichnung bei einem internationalen Computerprojekt-Wettbewerb für eine frühe technische Arbeit.","proof_documents.keyhorse.title":"Empfehlungsschreiben — KeyHorse","proof_documents.keyhorse.description":"Unterschriebene Empfehlung auf KeyHorse-Briefpapier, die Zhassulan für eine Senior-Engineering-Position empfiehlt.","projects.geonomix.description":"Groß angelegte Geodatenplattform und digitaler Zwilling, der interaktive Karten, kommunale Daten, digitale Register, öffentliche Dienstleistungen und Monitoring-Tools in regionalen Implementierungen vereint.","projects.midas-event.description":"Website einer Eventagentur, aufgebaut als durchstöberbares Portfolio vergangener Veranstaltungen statt als statische Leistungsliste, mit interaktiven Details in React.","projects.kostyum.description":"Responsives E-Commerce-Frontend für Herrenmode mit wiederverwendbarem Produktkatalog-UI und Fokus auf ein reibungsloses Einkaufserlebnis auf Desktop und Mobile.","projects.unistory.description":"Digitales Produktinterface, das Crypto-Wallet-Status und asynchrone Backend-Daten in wiederverwendbare React-Produktkomponenten integriert.","projects.kazmed.description":"Unternehmens-Frontend für einen autorisierten Servicepartner für medizinische Geräte, aufgebaut um einen Swiper-Katalog statt langer Textseiten.","projects.dostyk-trans-terminal.description":"Unternehmenswebsite eines Logistikterminals am Grenzübergang Dostyk–Alashankou, die Container-Umschlag-, Lager- und Transitdienste präsentiert.","projects.melissa.description":"Große Online-Apotheke mit über 13.000 Produkten, inklusive Katalog-Navigation, Suche, Filterung, Sortierung, Produktseiten, Warenkorb und Backend-Integrationen.","projects.abi-construction.description":"Website eines Bauunternehmens, die ein WordPress-CMS-Backend mit interaktiven Projektgalerien in Vue kombiniert.","projects.tahit.description":"Frontend eines Fertigungsunternehmens, das Textilproduktionskapazitäten, Technologie, Produkte und Dienstleistungen auf Desktop und Mobile präsentiert.","projects.dobraya.description":"Vitrine einer Online-Apotheke mit responsiven Katalogen, Kategorie-Navigation, Suche, Filterung und Checkout-Abläufen.","projects.asia-mebel.description":"Kommerzieller Katalog für Möbelmaterialien, Beschläge, Werkzeuge und Dienstleistungen mit strukturierter Navigation, Filterung, Suche und Produktseiten.","projects.pharmacom.description":"Website für ein Netzwerk von Impfkliniken und Apotheken, organisiert rund um Standorte, Dienstleistungen und Patienteninformationen statt einer einzigen statischen Startseite.","projects.navat.description":"Restaurant-Promo-Landingpage mit einem responsiven visuellen Erlebnis rund um Menü, Atmosphäre und Marke.","projects.asia-credit-bank.description":"Website des Kundenservice-Centers einer Bank, die eine große Anzahl von Produkt- und Support-Seiten in eine schnelle, leicht navigierbare Struktur verwandelt.","projects.geonomix.note":"Ein Produkt, bei dem die Karte im Mittelpunkt steht und Datenvolumen sowie wiederverwendbare regionale Auslieferung die Frontend-Architektur bestimmten.","projects.melissa.note":"Erfahrung mit einem großen Katalog, bei dem Informationsarchitektur genauso wichtig ist wie UI-Politur."},u={ru:n,kk:a,tr:o,zh:l,nl:c,de:d};function k(){const{locale:i}=r();return{tx:(t,s)=>{const e=u[i.value];return(e==null?void 0:e[t])??s}}}export{k as u};
